/**
 * Writes `fixtures/package/v10/elevation.buildbox`, its `project.json` and its asset (#75 §1).
 *
 * Run it with `npx vite-node scripts/make-v10-package-fixture.ts`. The file is an ordinary production
 * Backup — the format this build writes — so any build can run the generator. Like every golden file
 * it is committed bytes, never regenerated by a test; `fixtures.test.ts` proves these bytes still
 * round-trip.
 *
 * The scene is the v9 one beside it, unchanged, with the one thing the tenth schema added spelled out
 * on the Floor: two Elevation Views, one along the room and one at an angle. They are the bytes the
 * round-trip of a Project that holds Elevation Views is judged against.
 */
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { canonicalJsonBytes } from '../src/lib'
import { encodeProject } from '../src/package/encode'
import { FIXTURE_BUILD, FIXTURE_PLAN_IMAGE_HASH, elevationFixtureProject } from '../src/package/testing'

const assetBytes = readFileSync(join('fixtures', 'package', 'v8', 'assets', `${FIXTURE_PLAN_IMAGE_HASH}.png`))
const assetSource = async (): Promise<{ bytes: Uint8Array; mediaType: string }> => ({
  bytes: new Uint8Array(assetBytes),
  mediaType: 'image/png',
})

const project = elevationFixtureProject()
const bytes = await encodeProject(project, assetSource, FIXTURE_BUILD)

const dir = join('fixtures', 'package', 'v10')
mkdirSync(join(dir, 'assets'), { recursive: true })
writeFileSync(join(dir, 'elevation.buildbox'), bytes)
writeFileSync(join(dir, 'project.json'), `${new TextDecoder().decode(canonicalJsonBytes(project))}\n`)
copyFileSync(join('fixtures', 'package', 'v8', 'assets', `${FIXTURE_PLAN_IMAGE_HASH}.png`), join(dir, 'assets', `${FIXTURE_PLAN_IMAGE_HASH}.png`))
console.info(`wrote ${join(dir, 'elevation.buildbox')}: ${String(bytes.length)} bytes`)
